#!/usr/bin/env node
// Fetches up to 2 well-known people per name from Wikidata (E16b). Never generated by AI.
//
//   node scripts/names-content/fetch-people.mjs            # every name in the batches
//   node scripts/names-content/fetch-people.mjs --only 2   # only batch-002.json
//
// Needs network access to query.wikidata.org (run it on a machine that has it).
// Writes data/names/content-src/people.json; build-content.mjs then puts the people on the cards.
//
// Rules (E16 spec §8):
// - Humans whose given name (P735) is an item with this exact Hebrew label, with a Hebrew
//   Wikipedia article, ranked by number of Wikipedia sitelinks.
// - Excluded: politicians (occupation politician or any subclass), anyone who held a position (P39),
//   military officers and personnel, and every QID in people-exclude.json (flagged by the owner).
// - The person's Hebrew label must start with the name, and they need a Hebrew description,
//   which becomes the one-line "what". The description names the public role only.
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const srcDir = resolve(root, "data/names/content-src");
const ENDPOINT = "https://query.wikidata.org/sparql";
const UA = "NestNamesContent/1.0 (https://nestjourney.app; name cards, CC0 data)";
const CHUNK = 15;
const PER_NAME = 2;

const args = process.argv.slice(2);
const only = args.includes("--only") ? Number(args[args.indexOf("--only") + 1]) : null;

const readJson = (file) => JSON.parse(readFileSync(file, "utf8"));
const batchFiles = readdirSync(srcDir)
  .filter((f) => /^batch-\d+\.json$/.test(f))
  .filter((f) => only === null || Number(f.match(/\d+/)[0]) === only)
  .sort();
const names = [
  ...new Set([
    ...(only === null ? Object.keys(readJson(resolve(srcDir, "samples.json")).names) : []),
    ...batchFiles.flatMap((f) => Object.entries(readJson(resolve(srcDir, f)).names).filter(([, e]) => !e.hold).map(([n]) => n)),
  ]),
];
const excludeFile = resolve(srcDir, "people-exclude.json");
const exclude = new Set(existsSync(excludeFile) ? readJson(excludeFile).qids.map((q) => q.qid) : []);
const peopleFile = resolve(srcDir, "people.json");
const previous = existsSync(peopleFile) ? readJson(peopleFile) : { names: {} };

const query = (chunk) => `
SELECT ?name ?person ?label ?desc ?links WHERE {
  VALUES ?name { ${chunk.map((n) => JSON.stringify(n) + "@he").join(" ")} }
  VALUES ?gnType { wd:Q202444 wd:Q12308941 wd:Q11879590 wd:Q3409032 }
  ?gn rdfs:label ?name ; wdt:P31 ?gnType .
  ?person wdt:P735 ?gn ; wdt:P31 wd:Q5 ; wikibase:sitelinks ?links .
  ?article schema:about ?person ; schema:isPartOf <https://he.wikipedia.org/> .
  ?person rdfs:label ?label . FILTER(LANG(?label) = "he")
  ?person schema:description ?desc . FILTER(LANG(?desc) = "he")
  FILTER NOT EXISTS { ?person wdt:P106/wdt:P279* wd:Q82955 }
  FILTER NOT EXISTS { ?person wdt:P39 ?position }
  FILTER NOT EXISTS { VALUES ?mil { wd:Q189290 wd:Q47064 wd:Q4991371 } ?person wdt:P106 ?mil }
}`;

async function run(chunk, attempt = 1) {
  const res = await fetch(ENDPOINT, {
    method: "POST",
    headers: { "User-Agent": UA, Accept: "application/sparql-results+json", "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ query: query(chunk) }),
  });
  if (res.ok) return (await res.json()).results.bindings;
  if (attempt < 4 && (res.status === 429 || res.status >= 500)) {
    await new Promise((r) => setTimeout(r, 5000 * attempt));
    return run(chunk, attempt + 1);
  }
  throw new Error(`Wikidata ${res.status}: ${(await res.text()).slice(0, 300)}`);
}

const out = { ...previous.names };
for (let i = 0; i < names.length; i += CHUNK) {
  const chunk = names.slice(i, i + CHUNK);
  const rows = await run(chunk);
  const byName = new Map(chunk.map((n) => [n, new Map()]));
  for (const r of rows) {
    const qid = r.person.value.split("/").pop();
    const label = r.label.value;
    const name = r.name.value;
    if (exclude.has(qid)) continue;
    if (!(label === name || label.startsWith(name + " "))) continue;
    byName.get(name).set(qid, { name: label, what: r.desc.value, qid, links: Number(r.links.value) });
  }
  for (const [name, found] of byName) {
    out[name] = [...found.values()].sort((a, b) => b.links - a.links).slice(0, PER_NAME);
  }
  console.log(`${Math.min(i + CHUNK, names.length)}/${names.length}`);
  await new Promise((r) => setTimeout(r, 1000));
}

writeFileSync(
  peopleFile,
  JSON.stringify(
    {
      _about:
        "Known people per name, from Wikidata (CC0) by scripts/names-content/fetch-people.mjs. Do not add people by hand; to remove one, add the QID to people-exclude.json and run the script again.",
      fetchedAt: new Date().toISOString().slice(0, 10),
      names: Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b, "he"))),
    },
    null,
    1,
  ) + "\n",
);
console.log(`Wrote ${peopleFile}`);
